const DEFAULT_BORDER_COLOR_VARIABLE = 'var(--ricos-internal-table-border-color)';
const DEFAULT_BORDER_COLOR_FALLBACK = '#D3D3D3';

export const resolveDisplayedBorderColor = (
  color: string | undefined,
  defaultBorderColor: string
): string => (!color || color === DEFAULT_BORDER_COLOR_VARIABLE ? defaultBorderColor : color);

/**
 * Resolves the default table border color from the CSS variable
 * `--ricos-internal-table-border-color` on the nearest table container.
 *
 * The returned value is a raw CSS color string (could be hex, rgb, rgba,
 * relative color syntax, etc.).  It is safe for use in CSS / `FillPreview`
 * but may NOT be parseable by `toHexFormat`.
 */
export const resolveDefaultBorderColor = (editorDom: HTMLElement): string => {
  const tableContainer = editorDom.querySelector<HTMLElement>('[data-table-container]');
  if (!tableContainer) {
    return DEFAULT_BORDER_COLOR_FALLBACK;
  }
  const resolved = getComputedStyle(tableContainer)
    .getPropertyValue('--ricos-internal-table-border-color')
    .trim();

  return resolved || DEFAULT_BORDER_COLOR_FALLBACK;
};
