import React, { useContext, useMemo } from 'react';

import { RicosContext, RicosNodeContextProvider } from './../../ricos-context/index.js';
import type { TableNode } from './../../ricos-schema/next-schema/index.js';
import type { NodeViewRendererProps } from './../../ricos-types/index.js';

import { calculateBorderPadding } from '../borders/resolve-cell-borders.js';
import { TableBordersProvider } from '../borders/table-borders-context.js';
import { CELL_AUTO_MIN_WIDTH } from '../consts.js';
import { ROOT } from '../data-hooks.js';
import { TABLE_DEFAULTS, getMinColumnWidthForPadding, normalizePadding } from '../defaults.js';
import styles from '../statics/styles/table-viewer-scss.js';

/*
 * Calculate the total column count in a table row, accounting for colspan
 */
function calculateTableColumnCount(cells: $TSFixMe[] | undefined): number {
  if (!cells || cells.length === 0) {
    return 0;
  }
  return cells.reduce((sum: number, cell: $TSFixMe) => sum + (cell.tableCellData?.colspan || 1), 0);
}

/*
  The width passed to 'table-layout: fixed' columns serves as a ratio between
  columns, but columns won't get smaller than their width. The smallest possible
  values are already in the colsMinWidth table data property, so we normalize
  widths to be equal to or greater than colsMinWidth so they can shrink to
  min-width and stay proportional.
  Example:
  width:     20 30
  min-width: 10 10
  ratio:     2  3
  The smallest ratio is 2, we can divide everything by 2 and still keep all widths above min-width:
  width:     10 15

  If the min-widths are not equal, the algorithm holds; we will still keep the proportions:
  width:     20 45
  min-width: 10 15
  ratio:     2  3
  The smallest ratio is 2, we can divide everything by 2 and still keep all widths above min-width:
  width:     10 22.5
*/

function normalizeColumnWidths(
  colsMinWidths: number[],
  colsRelativeWidths: number[],
  paddingMinWidth: number
): { minWidth: number; width: number }[] {
  const colsWithDefaults = colsRelativeWidths.map((originalWidth, i) => {
    const minWidth = Math.max(colsMinWidths[i] || CELL_AUTO_MIN_WIDTH, paddingMinWidth);
    const width = originalWidth < minWidth ? minWidth : originalWidth;
    return {
      width,
      minWidth,
    };
  });
  const ratios = colsWithDefaults.map(c => c.width / c.minWidth);
  const smallestRatio = Math.min(...ratios);
  return colsWithDefaults.map(({ minWidth, width }) => ({
    minWidth,
    width: width / smallestRatio,
  }));
}

const TABLE_VERTICAL_PADDING = 16;

const TableSections: React.FC<{
  hasRowHeader: boolean;
  node: NodeViewRendererProps['node'];
  nodeIndex: number;
  RicosNodesRenderer: NodeViewRendererProps['RicosNodesRenderer'];
}> = ({ hasRowHeader, node, nodeIndex, RicosNodesRenderer }) => {
  const rows = node.nodes ?? [];
  // Skip thead/tbody split when a cell in row 0 has rowspan > 1,
  // because HTML rowspan cannot cross section boundaries.
  const headerRowHasRowspan =
    hasRowHeader && rows[0]?.nodes?.some(cell => (cell.tableCellData?.rowspan || 1) > 1);
  if (!hasRowHeader || headerRowHasRowspan || rows.length === 0) {
    return (
      <tbody>
        <RicosNodeContextProvider parentNode={node} parentIndex={nodeIndex}>
          <RicosNodesRenderer nodes={rows} />
        </RicosNodeContextProvider>
      </tbody>
    );
  }
  const headerRows = rows.slice(0, 1);
  const bodyRows = rows.slice(1);
  return (
    <>
      <thead>
        <RicosNodeContextProvider parentNode={node} parentIndex={nodeIndex}>
          <RicosNodesRenderer nodes={headerRows} />
        </RicosNodeContextProvider>
      </thead>
      {bodyRows.length > 0 && (
        <tbody>
          <RicosNodeContextProvider parentNode={node} parentIndex={nodeIndex}>
            <RicosNodesRenderer nodes={bodyRows} />
          </RicosNodeContextProvider>
        </tbody>
      )}
    </>
  );
};

const Table = ({
  node,
  nodeIndex,
  RicosNodesRenderer,
  NodeViewContainer,
}: NodeViewRendererProps) => {
  const borderPadding = useMemo(() => calculateBorderPadding(node as TableNode), [node]);
  const { languageDir } = useContext(RicosContext);
  const isRTL = languageDir === 'rtl';
  const { dimensions: { colsMinWidth = [], colsWidthRatio = [] } = {} } = node.tableData || {};
  const cellSpacing = (node.tableData?.cellSpacing as number | undefined) ?? 0;
  const cellPadding = normalizePadding(node.tableData?.cellPadding, [
    ...TABLE_DEFAULTS.cellPadding,
  ]);

  // Calculate actual column count from table structure
  const actualColumnCount = node.nodes
    ? Math.max(0, ...node.nodes.map(row => calculateTableColumnCount(row.nodes)))
    : 0;

  const paddingMinWidth = getMinColumnWidthForPadding(node.tableData?.cellPadding);

  const colStyles = normalizeColumnWidths(colsMinWidth, colsWidthRatio, paddingMinWidth);

  // Pad colStyles to match actual column count if dimensions are missing for some columns
  const columnsToRender = Array.from({ length: actualColumnCount }, (_, index) => {
    if (index < colStyles.length) {
      return colStyles[index];
    }
    // Use default width for columns beyond the dimensions array
    return {
      minWidth: paddingMinWidth,
      width: paddingMinWidth,
    };
  });

  const viewportStyle = {
    '--table-border-top': `${borderPadding.top}px`,
    '--table-border-bottom': `${borderPadding.bottom}px`,
    '--table-border-start': `${borderPadding.start}px`,
    '--table-border-end': `${borderPadding.end}px`,
    '--table-vertical-padding': `${TABLE_VERTICAL_PADDING}px`,
    ...(cellPadding && cellPadding.length > 0
      ? {
          '--ricos-internal-table-cell-padding-top': `${cellPadding[0]}px`,
          '--ricos-internal-table-cell-padding-right': `${cellPadding[1] ?? cellPadding[0]}px`,
          '--ricos-internal-table-cell-padding-bottom': `${cellPadding[2] ?? cellPadding[0]}px`,
          '--ricos-internal-table-cell-padding-left': `${
            cellPadding[3] ?? cellPadding[1] ?? cellPadding[0]
          }px`,
        }
      : {}),
    '--ricos-internal-table-gap': `${cellSpacing}px`,
  } as React.CSSProperties;

  const hasRowHeader = !!node.tableData?.rowHeader;
  const altText = node.tableData?.altText;

  return (
    <NodeViewContainer node={node} nodeIndex={nodeIndex}>
      <TableBordersProvider tableNode={node as TableNode} isRTL={isRTL}>
        <div className={styles.tableViewport} style={viewportStyle}>
          <table
            className={styles.container}
            data-hook={ROOT}
            aria-label={altText || undefined}
            style={{
              borderSpacing: '0',
              borderCollapse: 'separate',
            }}
          >
            <colgroup>
              {columnsToRender.map((colStyle, index) => {
                // Add spacing to width for non-first columns (transparent borders increase cell width)
                const width =
                  index > 0 && cellSpacing > 0 ? colStyle.width + cellSpacing : colStyle.width;
                return <col key={index} style={{ width, minWidth: colStyle.minWidth }} />;
              })}
            </colgroup>
            <TableSections
              hasRowHeader={hasRowHeader}
              node={node}
              nodeIndex={nodeIndex}
              RicosNodesRenderer={RicosNodesRenderer}
            />
          </table>
        </div>
      </TableBordersProvider>
    </NodeViewContainer>
  );
};

const TableRenderer = ({ node, ...props }: NodeViewRendererProps) => {
  return (
    <div className={styles.root} key={node.id}>
      <Table node={node} {...props} />
    </div>
  );
};

export default TableRenderer;
